mapper.select:
select t.ecif_change_id, t.bp_id, t.oprtn_ind, t.cst_no, t.cst_nm_s, t.ident_no, t.inst_ident_tp, t.unifd_socl_crdt_cd, t.cst_tp, t.ovrs_cst_chin_nm, t.rgstrtn_cty_and_dstc_cd, t.maincorprtnactvctyordstccd, t.cst_lo_natl_std_idy, t.swiftno, t.entp_atch_rltnp, t.ecnm_tp, t.lgl_rprs_nm, t.corprtn_scop1, t.crdt_cst_flg, t.org_cust_type, t.business_date, t.submit_user_id, t.submit_date, t.wfl_status, t.wfl_instance_id, t.change_number from ws_ecif_bp_master_change t WHERE 1=1
and t.bp_id= #{bpId}
and t.wfl_status in ('APPROVED_RETURN','NEW')

select t.ecif_change_id, t.bp_id, t.oprtn_ind, t.cst_no, t.cst_nm_s, t.ident_no, t.inst_ident_tp, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'BP.REGISTRATION_NUM_TYPE' AND v.code_value = t.inst_ident_tp ) inst_ident_tp_n, t.unifd_socl_crdt_cd, t.cst_tp, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HLS.CUSTOMER_TYPE' AND v.code_value = t.cst_tp ) cst_tp_n, t.ovrs_cst_chin_nm, t.rgstrtn_cty_and_dstc_cd, (select fc.country_name from fnd_country fc where fc.country=t.rgstrtn_cty_and_dstc_cd)rgstrtn_cty_and_dstc_cd_n, t.maincorprtnactvctyordstccd, (select fc.country_name from fnd_country fc where fc.country=t.maincorprtnactvctyordstccd)maincorprtnactvctyordstccd_n, t.cst_lo_natl_std_idy, (select hsc.description from hls_stat_class hsc where hsc.class_id=t.cst_lo_natl_std_idy)cst_lo_natl_std_idy_n, t.swiftno, t.entp_atch_rltnp, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'HLS.ENTERPRISE_AFFILIATION' AND v.code_value = t.entp_atch_rltnp ) entp_atch_rltnp_n, t.ecnm_tp, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'ZX_ECONOMICTYPE' AND v.code_value = t.ecnm_tp ) ecnm_tp_n, t.lgl_rprs_nm, t.corprtn_scop1, t.crdt_cst_flg, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'SYS.YES_NO' AND v.code_value = t.crdt_cst_flg ) crdt_cst_flg_n, t.org_cust_type, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'BP.BP_MASTER_ROLE' AND v.code_value = t.org_cust_type ) org_cust_type_n, t.business_date, t.submit_user_id, nvl(t.operator_user,(select su.description from sys_user su,hls_bp_master h where su.user_id=h.created_by and h.bp_id=t.bp_id))submit_user_id_n, t.submit_date, t.wfl_status, (select hd.description from hls_document_status hd where hd.document_category='BP_ECIF_CHANGE' and hd.status_code=t.wfl_status)wfl_status_n, t.wfl_instance_id, t.change_number, t.msg from ws_ecif_bp_master_change t WHERE 1=1
and t.bp_id = #{bpId}
order by t.ecif_change_id desc
